DROP VIEW IF EXISTS `HumanResources_vEmployee`;
CREATE VIEW `HumanResources_vEmployee` AS
select `e`.`BusinessEntityID` AS `BusinessEntityID`,`p`.`Title` AS `Title`,`p`.`FirstName` AS `FirstName`,`p`.`MiddleName` AS `MiddleName`,`p`.`LastName` AS `LastName`,`p`.`Suffix` AS `Suffix`,`e`.`JobTitle` AS `JobTitle`,`pp`.`PhoneNumber` AS `PhoneNumber`,`pnt`.`Name` AS `PhoneNumberType`,`ea`.`EmailAddress` AS `EmailAddress`,`p`.`EmailPromotion` AS `EmailPromotion`,`a`.`AddressLine1` AS `AddressLine1`,`a`.`AddressLine2` AS `AddressLine2`,`a`.`City` AS `City`,`sp`.`Name` AS `StateProvinceName`,`a`.`PostalCode` AS `PostalCode`,`cr`.`Name` AS `CountryRegionName`,`p`.`AdditionalContactInfo` AS `AdditionalContactInfo` from ((((((((`adventureworks`.`HumanResources_Employee` `e` join `adventureworks`.`Person_Person` `p` on((`p`.`BusinessEntityID` = `e`.`BusinessEntityID`))) join `adventureworks`.`Person_BusinessEntityAddress` `bea` on((`bea`.`BusinessEntityID` = `e`.`BusinessEntityID`))) join `adventureworks`.`Person_Address` `a` on((`a`.`AddressID` = `bea`.`AddressID`))) join `adventureworks`.`Person_StateProvince` `sp` on((`sp`.`StateProvinceID` = `a`.`StateProvinceID`))) join `adventureworks`.`Person_CountryRegion` `cr` on((`cr`.`CountryRegionCode` = `sp`.`CountryRegionCode`))) left join `adventureworks`.`Person_PersonPhone` `pp` on((`pp`.`BusinessEntityID` = `p`.`BusinessEntityID`))) left join `adventureworks`.`Person_PhoneNumberType` `pnt` on((`pp`.`PhoneNumberTypeID` = `pnt`.`PhoneNumberTypeID`))) left join `adventureworks`.`Person_EmailAddress` `ea` on((`p`.`BusinessEntityID` = `ea`.`BusinessEntityID`)))